'use strict';
globalThis.IslandPlayers=(()=>{
 const models=new Map();let instance=null,loading=null;
 function load(){return loading??=Promise.all(['fox','bunny'].map(async kind=>{const response=await fetch('assets/island-players/'+kind+'.json');if(!response.ok)throw Error(kind+'模型读取失败');const data=await response.json(),image=new Image();await new Promise((resolve,reject)=>{image.onload=resolve;image.onerror=reject;image.src='assets/island-players/'+kind+'.png';});if(!data.vertices.every(Number.isFinite)||data.vertices.length%45)throw Error(kind+'网格无效');models.set(kind,{...data,image,vertices:new Float32Array(data.vertices),pose:new Float32Array(29*12),gpu:null,uploads:0});})).catch(e=>console.warn('狐狸/兔子加载失败，保留原角色',e));}
 function draw(kind,at){const m=models.get(kind);if(!m)return false;const idle=m.clips.idle,walk=m.clips.walk,blend=at.mounted?0:at.blend||0;
  function sample(clip,i){const f=((at.time*clip.fps)%clip.frames.length+clip.frames.length)%clip.frames.length,j=Math.floor(f),a=clip.frames[j],b=clip.frames[(j+1)%clip.frames.length];return a[i]+(b[i]-a[i])*(f-j);}
  for(let i=0;i<m.bones.length*12;i++)m.pose[i]=sample(idle,i)*(1-blend)+sample(walk,i)*blend;
  const pivot=m.bind['mixamorig:Head'].head,pitch=(at.headPitch||0)-(at.cameraTilt||0),roll=at.headRoll||0,cp=Math.cos(pitch),sp=Math.sin(pitch),cr=Math.cos(roll),sr=Math.sin(roll);
  for(const name of ['mixamorig:Head','mixamorig:HeadTop_End']){const i=m.bones.indexOf(name)*12;if(i<0)continue;
   for(let col=0;col<4;col++){const w=col===3?1:0,x=m.pose[i+col]-pivot[0]*w,y=m.pose[i+4+col]-pivot[1]*w,z=m.pose[i+8+col]-pivot[2]*w,rx=cr*x-sr*y,ry=sr*x+cr*y;m.pose[i+col]=rx+pivot[0]*w;m.pose[i+4+col]=cp*ry-sp*z+pivot[1]*w;m.pose[i+8+col]=sp*ry+cp*z+pivot[2]*w;}}
  instance={kind,m,...at,size:at.size*1.12};return true;
 }
 function initialize(r,m){if(m.gpu?.marker===r.program)return m.gpu;const gl=r.gl,compile=(type,src)=>{const s=gl.createShader(type);gl.shaderSource(s,src);gl.compileShader(s);if(!gl.getShaderParameter(s,gl.COMPILE_STATUS))throw Error(gl.getShaderInfoLog(s));return s;};
  const vs=compile(gl.VERTEX_SHADER,`attribute vec3 p;attribute vec3 n;attribute vec2 uv;attribute vec3 joints;attribute vec3 weights;attribute float eye;uniform vec4 bones[87];uniform mat4 vp;uniform vec3 origin;uniform float size;varying vec2 texcoord;varying vec3 normal;varying float eyeMask;void main(){vec4 v=vec4(p,1.);vec3 at=vec3(0.),norm=vec3(0.);for(int j=0;j<3;j++){int i=int(joints[j])*3;at+=vec3(dot(bones[i],v),dot(bones[i+1],v),dot(bones[i+2],v))*weights[j];norm+=vec3(dot(bones[i].xyz,n),dot(bones[i+1].xyz,n),dot(bones[i+2].xyz,n))*weights[j];}normal=normalize(norm);texcoord=uv;eyeMask=eye;gl_Position=vp*vec4(origin+at*size,1.);}`);
  const fs=compile(gl.FRAGMENT_SHADER,`precision highp float;uniform sampler2D image;uniform float mode;uniform float emission;uniform float flash;uniform vec2 gaze;uniform vec3 pupilColor;uniform float pupilSize;uniform vec3 eyeWhiteColor;uniform float pupilSlit;varying vec2 texcoord;varying vec3 normal;varying float eyeMask;${globalThis.CharacterGaze.eyeGLSL}${globalThis.CharacterEyes.shaderGLSL}vec2 depth(){vec2 d=fract(min(gl_FragCoord.z,.999999)*vec2(1.,255.));d.x-=d.y/255.;return d;}vec2 oct(vec3 n){n/=abs(n.x)+abs(n.y)+abs(n.z);vec2 o=n.xy;if(n.z<0.)o=(1.-abs(o.yx))*sign(o.xy+vec2(.00001));return o*.5+.5;}void main(){if(mode>-.5){if(mode<.5)gl_FragColor=vec4(depth(),1.,1.);else if(mode<1.5){vec2 o=oct(normalize(normal));gl_FragColor=vec4(depth(),o.x*.49,o.y);}else if(mode<2.5)gl_FragColor=vec4(depth(),0.,1.);else gl_FragColor=vec4(vec3(emission),1.);return;}vec3 base=texture2D(image,texcoord).rgb;if(eyeMask>.5){base=characterIris(texcoord,gaze,eyeWhiteColor,pupilColor,pupilSize,pupilSlit);}float light=.55+.4*max(0.,dot(normalize(normal),normalize(vec3(-.4,.85,.45))));gl_FragColor=vec4(mix(mix(base*light,base*1.08,emission),vec3(1.,.95,.7),flash),1.);}`);
  const program=gl.createProgram();gl.attachShader(program,vs);gl.attachShader(program,fs);gl.linkProgram(program);if(!gl.getProgramParameter(program,gl.LINK_STATUS))throw Error(gl.getProgramInfoLog(program));gl.deleteShader(vs);gl.deleteShader(fs);const buffer=gl.createBuffer();gl.bindBuffer(gl.ARRAY_BUFFER,buffer);gl.bufferData(gl.ARRAY_BUFFER,m.vertices,gl.STATIC_DRAW);m.uploads++;const texture=gl.createTexture();gl.bindTexture(gl.TEXTURE_2D,texture);gl.pixelStorei(gl.UNPACK_FLIP_Y_WEBGL,true);gl.texImage2D(gl.TEXTURE_2D,0,gl.RGBA,gl.RGBA,gl.UNSIGNED_BYTE,m.image);gl.pixelStorei(gl.UNPACK_FLIP_Y_WEBGL,false);for(const [p,v]of [[gl.TEXTURE_MIN_FILTER,gl.LINEAR],[gl.TEXTURE_MAG_FILTER,gl.LINEAR],[gl.TEXTURE_WRAP_S,gl.CLAMP_TO_EDGE],[gl.TEXTURE_WRAP_T,gl.CLAMP_TO_EDGE]])gl.texParameteri(gl.TEXTURE_2D,p,v);
  return m.gpu={marker:r.program,program,buffer,texture,u:Object.fromEntries(['bones[0]','vp','origin','size','image','mode','emission','flash','gaze','pupilColor','pupilSize','eyeWhiteColor','pupilSlit'].map(n=>[n,gl.getUniformLocation(program,n)]))};
 }
 function renderGeometry(r,matrix,mode){if(!instance)return;const at=instance,m=at.m,g=initialize(r,m),gl=r.gl,u=g.u;gl.useProgram(g.program);gl.uniform4fv(u['bones[0]'],m.pose);gl.uniformMatrix4fv(u.vp,false,matrix);gl.uniform3f(u.origin,at.x,at.y,at.z);gl.uniform1f(u.size,at.size);gl.uniform1f(u.mode,mode);gl.uniform1f(u.emission,globalThis.CatPlayer.emission);gl.uniform1f(u.flash,at.flash||0);const gaze=globalThis.CharacterGaze?.current;gl.uniform2f(u.gaze,gaze?.x||0,gaze?.y||0);gl.uniform3fv(u.pupilColor,globalThis.CharacterEyes?.rgb(at.kind)||[.015,.01,.005]);gl.uniform1f(u.pupilSize,globalThis.CharacterEyes?.get(at.kind).size||.676);gl.uniform3fv(u.eyeWhiteColor,globalThis.CharacterEyes.whiteRGB(at.kind));gl.uniform1f(u.pupilSlit,globalThis.CharacterEyes.get(at.kind).slit);gl.activeTexture(gl.TEXTURE0);gl.bindTexture(gl.TEXTURE_2D,g.texture);gl.uniform1i(u.image,0);gl.bindBuffer(gl.ARRAY_BUFFER,g.buffer);r.attributes(g.program,[['p',3],['n',3],['uv',2],['joints',3],['weights',3],['eye',1]],60);gl.drawArrays(gl.TRIANGLES,0,m.vertices.length/15);}
 return {load,ready:kind=>models.has(kind),draw,begin(){instance=null;},render(r){if(!instance)return;r.gl.disable(r.gl.BLEND);r.gl.depthMask(true);renderGeometry(r,r.vp,-1);},renderGeometry,get stats(){return {instance:instance?.kind||null,models:[...models].map(([kind,m])=>({kind,bones:m.bones.length,vertices:m.vertices.length/15,uploads:m.uploads}))};}};
})();
